namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings

<nav class="settings-nav">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (Profile is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@editableProfile.AvatarUrl" alt="Avatar" class="avatar-img" />
                <span class="avatar-url">@editableProfile.AvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editableProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editableProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="editableProfile.Bio" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast @statusClass">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileModel editableProfile = new();
    private string statusMessage = "";
    private string statusClass = "";

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasEdited)
        {
            ResetForm();
        }
    }

    private bool hasEdited;

    private void ResetForm()
    {
        if (Profile is null) return;
        editableProfile = new ProfileModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
        hasEdited = false;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(
            editableProfile.DisplayName,
            editableProfile.Email,
            editableProfile.AvatarUrl,
            editableProfile.Bio);
        await OnSave.InvokeAsync(updated);
        hasEdited = false;
        statusMessage = "Profile saved successfully!";
        statusClass = "toast-success";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        ResetForm();
        statusMessage = "Changes discarded.";
        statusClass = "toast-info";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (Prefs is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast toast-success">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private string statusMessage = "";

    // Available channels for demonstration
    private static readonly string[] allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(
            emailNotifications,
            pushNotifications,
            weeklyDigest,
            mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        statusMessage = "Preferences saved!";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings

<div class="expandable-panel">
    <button class="panel-header" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span class="expand-icon">@(isExpanded ? "▼" : "▶")</span>
    </button>

    @if (isExpanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="toast toast-error">@errorMessage</div>
            }
            @if (!string.IsNullOrEmpty(successMessage))
            {
                <div class="toast toast-success">@successMessage</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string errorMessage = "";
    private string successMessage = "";

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = "";
        successMessage = "";

        if (string.IsNullOrWhiteSpace(currentPassword) ||
            string.IsNullOrWhiteSpace(newPassword) ||
            string.IsNullOrWhiteSpace(confirmPassword))
        {
            errorMessage = "All fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        successMessage = "Password updated successfully!";
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (sessionToRevoke is not null)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
