    private bool hasEdited;

    private void ResetForm()
    {
        if (Profile is null) return;
        editableProfile = new ProfileModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
