            editableProfile.DisplayName,
            editableProfile.Email,
            editableProfile.AvatarUrl,
            editableProfile.Bio);
        await OnSave.InvokeAsync(updated);
        hasEdited = false;
        statusMessage = "Profile saved successfully!";
        statusClass = "toast-success";
