@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings

<div class="expandable-panel">
    <button class="panel-header" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span class="expand-icon">@(isExpanded ? "▼" : "▶")</span>
    </button>

    @if (isExpanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="toast toast-error">@errorMessage</div>
            }
            @if (!string.IsNullOrEmpty(successMessage))
            {
                <div class="toast toast-success">@successMessage</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string errorMessage = "";
    private string successMessage = "";

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePasswordAsync()
    {
        errorMessage = "";
        successMessage = "";

        if (string.IsNullOrWhiteSpace(currentPassword) ||
            string.IsNullOrWhiteSpace(newPassword) ||
            string.IsNullOrWhiteSpace(confirmPassword))
        {
            errorMessage = "All fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            errorMessage = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        successMessage = "Password updated successfully!";
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }
}

