@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (sessionToRevoke is not null)
    {
        <div class="confirm-dialog-overlay">
            <div class="confirm-dialog">
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? sessionToRevoke;

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;

    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }
}

@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-on" : "status-off")"></span>
                <span>@(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")</span>
            </div>
            @if (Settings.LastPasswordChange.HasValue)
            {
                <p class="last-change">Last password change: @Settings.LastPasswordChange.Value.ToString("D")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="Settings.Sessions"
                             CurrentSessionId="@currentSessionId"
                             OnRevoke="HandleRevoke" />
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    // First session is treated as the current session
    private string currentSessionId => Settings?.Sessions.FirstOrDefault()?.Id ?? "";

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
    }
}

