@namespace sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Components.Pages.Settings
@using sv_6b1e3330f6be4b91bd0e4a7bb484a0f8.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (Settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label><input type="radio" name="theme" value="Light" checked="@(selectedTheme == "Light")" @onchange="() => selectedTheme = &quot;Light&quot;" /> Light</label>
                    <label><input type="radio" name="theme" value="Dark" checked="@(selectedTheme == "Dark")" @onchange="() => selectedTheme = &quot;Dark&quot;" /> Dark</label>
                    <label><input type="radio" name="theme" value="System" checked="@(selectedTheme == "System")" @onchange="() => selectedTheme = &quot;System&quot;" /> System</label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label><input type="radio" name="fontSize" value="Small" checked="@(selectedFontSize == "Small")" @onchange="() => selectedFontSize = &quot;Small&quot;" /> Small</label>
                    <label><input type="radio" name="fontSize" value="Medium" checked="@(selectedFontSize == "Medium")" @onchange="() => selectedFontSize = &quot;Medium&quot;" /> Medium</label>
                    <label><input type="radio" name="fontSize" value="Large" checked="@(selectedFontSize == "Large")" @onchange="() => selectedFontSize = &quot;Large&quot;" /> Large</label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="compactMode" class="toggle-switch" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <div class="preview-area">
                <h4>Live Preview</h4>
                <div class="preview-box @GetPreviewClasses()">
                    <p class="preview-heading">Sample Heading</p>
                    <p class="preview-text">This is how your content will look with the selected settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="toast toast-success">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private string statusMessage = "";

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{selectedTheme.ToLowerInvariant()} preview-font-{selectedFontSize.ToLowerInvariant()}";
        if (compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        statusMessage = "Appearance saved!";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        statusMessage = "";
        await InvokeAsync(StateHasChanged);
    }
}

